def find_multiple():
    # We need to find the least common multiple (LCM) of 9 and 12
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    multiple_of_9_and_12 = lcm(9, 12)

    # Check which of the given choices is a multiple of the LCM
    choices = [36, 15, 17, 5, 7]
    for choice in choices:
        if choice % multiple_of_9_and_12 == 0:
            return choice

answer = find_multiple()
